package com.studysync.controller;
import com.studysync.dao.GroupDAO; import com.studysync.model.*; import com.studysync.util.JsonUtil; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; import java.util.*;
@WebServlet("/api/groups") public class GroupServlet extends HttpServlet {private GroupDAO dao=new GroupDAO(); protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{User u=(User)q.getSession().getAttribute("user");if(u==null){JsonUtil.send(r,"{\"ok\":false,\"message\":\"Login required\"}");return;}String a=q.getParameter("action");if("create".equals(a)){String code=UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();Group g=new Group(0,q.getParameter("name"),q.getParameter("subject"),q.getParameter("description"),code,u.getId());int id=dao.save(g);dao.addMember(id,u.getId());JsonUtil.send(r,"{\"ok\":true,\"id\":"+id+",\"code\":\""+code+"\"}");}else if("join".equals(a)){Group g=dao.findByCode(q.getParameter("code"));if(g==null){JsonUtil.send(r,"{\"ok\":false,\"message\":\"Room not found\"}");return;}dao.addMember(g.getId(),u.getId());JsonUtil.send(r,"{\"ok\":true,\"message\":\"Joined room\"}");}}catch(Exception e){JsonUtil.send(r,"{\"ok\":false,\"message\":\"Server error\"}");}}}
